1057	      console.log('[PASTE] target input:', input ? `col=${input.dataset.col}, sortedIdx=${input.dataset.sortedIdx}` : 'NOT FOUND');
1058	      if (!input) return; // not pasting into our editable cell
1059	
1060	      const pasteText = (e.clipboardData || window.clipboardData).getData('text');
