752	function sortTable(th, colIdx) {
753	  const table = th.closest("table");
754	  const tbody = table.querySelector("tbody");
755	  const rows = Array.from(tbody.querySelectorAll("tr"));
756	  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
757	
758	  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
759	  th.classList.add("sorted");
760	  if (isDesc) th.classList.add("desc");
761	
762	  // Determine which heroes list is active
763	  let heroes;
764	  if (gameData.hasLanes) {
765	    if (currentView === "global") {
766	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
767	    } else {
768	      heroes = gameData.lanes[currentLane] || [];
769	    }
770	  } else {
771	    heroes = gameData.heroes;
772	  }
773	
774	  // Build column definitions
775	  let cols;
776	  if (gameData.hasLanes && currentView === "global") {
777	    cols = gameConfig.globalColumns;
778	  } else {
779	    cols = gameConfig.columns;
780	  }
781	
782	  // Handle lane-specific rank column
783	  const col = (colIdx < cols.length) ? cols[colIdx] : { field: "globalRank", type: "rank" };
784	
785	  // 动态找到英雄名列的索引（而非硬编码 cells[1]）
786	  const nameColIdx = cols.findIndex(c => c.field === "name");
787	  rows.sort((a, b) => {
788	    const heroA = heroes.find(h => h.name === a.cells[nameColIdx]?.textContent?.trim());
789	    const heroB = heroes.find(h => h.name === b.cells[nameColIdx]?.textContent?.trim());
790	    const va = heroA ? (col.field === "laneRank" ? heroA.laneRank : heroA[col.field]) : 0;
791	    const vb = heroB ? (col.field === "laneRank" ? heroB.laneRank : heroB[col.field]) : 0;
792	
793	    if (col.type === "tier") {
794	      const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
795	      const ia = order.indexOf(va), ib = order.indexOf(vb);
796	      return isDesc ? ib - ia : ia - ib;
797	    }
798	    const na = parseFloat(va), nb = parseFloat(vb);
799	    if (!isNaN(na) && !isNaN(nb)) {
800	      return isDesc ? nb - na : na - nb;
801	    }
802	    const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
803	    return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
804	  });
805	
806	  rows.forEach(r => tbody.appendChild(r));
807	}
