14	function mean(a) { return a.reduce((s,v)=>s+v,0)/a.length; }
15	function std(a) { const m=mean(a); return Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/a.length); }
16	function minmax(arr) { const lo=Math.min(...arr), hi=Math.max(...arr); return arr.map(v=>(v-lo)/(hi-lo||1)); }
17	function cv(arr) { return std(arr)/Math.abs(mean(arr)); }
